    def xǁMemoryStorageǁupdate_memory__mutmut_orig(self, memory_id: int, importance: float, tags: List[str]) -> bool:
        """
        Update existing memory's importance and tags.
        
        Args:
            memory_id: ID of memory to update
            importance: New importance score
            tags: New tags list
            
        Returns:
            True if update successful, False otherwise
        """
        self._ensure_connection()
        
        try:
            cursor = self._connection.cursor()
            
            # Convert tags to JSON
            tags_json = json.dumps(tags)
            
            # Update memory
            cursor.execute("""
                UPDATE memories 
                SET importance = ?, tags = ?, last_used_at = ?
                WHERE id = ?
            """, (
                importance,
                tags_json,
                datetime.now(timezone.utc).isoformat(),
                memory_id
            ))
            
            self._connection.commit()
            
            if cursor.rowcount > 0:
                logger.debug(f"Updated memory {memory_id} with importance {importance}")
                return True
            else:
                logger.warning(f"Memory {memory_id} not found for update")
                return False
                
        except Exception as e:
            logger.error(f"Error updating memory {memory_id}: {e}", exc_info=True)
            return False
    
