    def xǁMemoryStorageǁstore_memory__mutmut_orig(self, record: MemoryRecord, embedding: Optional[List[float]] = None) -> int:
        """
        Store a memory record in the database.
        
        Args:
            record: MemoryRecord to store
            embedding: Optional embedding vector (not stored in DB, handled by vector index)
            
        Returns:
            ID of the stored memory
        """
        self._ensure_connection()
        
        cursor = self._connection.cursor()
        
        # Convert tags to JSON
        tags_json = json.dumps(record.tags)
        
        # Convert datetimes to ISO format strings
        created_at_str = record.created_at.isoformat()
        last_used_at_str = record.last_used_at.isoformat()
        valid_from_str = record.valid_from.isoformat() if record.valid_from else None
        valid_until_str = record.valid_until.isoformat() if record.valid_until else None
        
        # Convert embedding to JSON if provided
        embedding_json = json.dumps(embedding) if embedding else None
        
        # Convert source to database format
        source_type_str = None
        source_metadata_json = None
        if record.source is not None:
            source_type_str = record.source.source_type.value
            source_metadata_json = json.dumps(record.source.metadata) if record.source.metadata else None
        
        cursor.execute("""
            INSERT INTO memories (namespace, tags, text, importance, created_at, last_used_at, embedding, valid_from, valid_until, temporal_scope, source_type, source_metadata)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            record.namespace,
            tags_json,
            record.text,
            record.importance,
            created_at_str,
            last_used_at_str,
            embedding_json,
            valid_from_str,
            valid_until_str,
            record.temporal_scope,
            source_type_str,
            source_metadata_json
        ))
        
        memory_id = cursor.lastrowid
        self._connection.commit()
        
        logger.debug(f"Stored memory with ID: {memory_id}")
        return memory_id
    
